/bin/zsh -lc "node --input-type=module <<'RELAYER_GRAPH_PROGRAM'
import { RelayerGraphClient, NodeObject, EdgeObject, LayerObject, NodePlacementObject, LayerLayoutObject, html, css, detailCapability } from 'file:///Users/[redacted]/Desktop/relayer-graphcomplete/packages/graph-client/dist/index.js';
const graph = RelayerGraphClient.fromEnv();
const current = await graph.getCurrent();
const style = css"'`
.page { font-family: system-ui, sans-serif; padding: 24px; line-height: 1.55; max-width: 850px; }
h2 { margin: 0 0 12px; font-size: 25px; } h3 { margin: 20px 0 6px; font-size: 18px; }
p { margin: 8px 0; } .lead { font-size: 18px; } .flow { display: flex; flex-wrap: wrap; gap: 8px; margin: 18px 0; align-items: center; } .step { border: 1px solid; padding: 8px 12px; border-radius: 8px; } .note { border-left: 3px solid; padding: 8px 14px; margin-top: 16px; } button { font: inherit; border: 1px solid; border-radius: 8px; padding: 10px 14px; margin-top: 16px; cursor: pointer; } button:focus-visible { outline: 3px solid #478bcb; outline-offset: 3px; } table { border-collapse: collapse; width: 100%; margin: 16px 0; } td, th { text-align: left; vertical-align: top; border-bottom: 1px solid; padding: 10px; } code { font-size: 0.93em; }
[data-relayer-theme="light"] .page { color: #182b35; background-color: #fafbf9; } [data-relayer-theme="light"] .step, [data-relayer-theme="light"] button { background-color: #edf3f5; border-color: #a4b8c1; color: #182b35; } [data-relayer-theme="light"] td, [data-relayer-theme="light"] th { border-color: #ccd6dc; } [data-relayer-theme="light"] .note { border-color: #346a89; background-color: #eef4f6; } [data-relayer-theme="light"] button:hover { background-color: #dce9ef; }
[data-relayer-theme="dark"] .page { color: #edf2f3; background-color: #171e23; } [data-relayer-theme="dark"] .step, [data-relayer-theme="dark"] button { background-color: #25353e; border-color: #6b8593; color: #edf2f3; } [data-relayer-theme="dark"] td, [data-relayer-theme="dark"] th { border-color: #49616d; } [data-relayer-theme="dark"] .note { border-color: #89bedb; background-color: #24323b; } [data-relayer-theme="dark"] button:hover { background-color: #354b57; }
`;
const data = new NodeObject('"'database','1 · Prepare text','Collect and curate text; clean, deduplicate, filter and separate evaluation data. Output: a versioned training corpus.','concept','text-stage');
const tokens = new NodeObject('binary','2 · Make tokens','Encode text as token IDs, then pack token sequences into batches. Output: model-ready examples.','concept','token-stage');
const train = new NodeObject('brain','3 · Pretrain','A causal transformer predicts the next token. Backpropagation and an optimizer adjust its weights across many batches. Output: a base model.','concept','pretrain-stage');
const adapt = new NodeObject('messages-square','4 · Adapt behavior','Often add instruction tuning and preference optimization. Output: a model shaped for intended tasks and interactions.','concept','adapt-stage');
const deploy = new NodeObject('rocket','5 · Evaluate & deploy','Test capability, reliability and risk; optimize serving and release with monitoring. Output: a deployed model and feedback for the next version.','concept','deploy-stage');
const learning = new NodeObject('brain','How the model learns','Token embeddings and causal attention produce next-token probabilities. Cross-entropy measures prediction error; gradients update weights.','concept','learning-detail');
const release = new NodeObject('clipboard-check','From checkpoint to service','Evaluate before release, balance inference cost against quality, and monitor real usage. Evaluation data stays separate from training.','concept','release-detail');
const rootNodes = [data,tokens,train,adapt,deploy];
const edges = rootNodes.slice(1).map((n,i)=>new EdgeObject([rootNodes[i],n],"'`pipeline-edge-${i+1}`));
const root = new LayerObject(rootNodes,edges,new LayerLayoutObject(rootNodes.map((n,i)=>new NodePlacementObject(n,0.08+i*0.21,0.5)),'"'elbow-horizontal'),'training-map-root'); root.defaultNode=train;
const learnLayer = new LayerObject([learning],[],new LayerLayoutObject([new NodePlacementObject(learning,0.5,0.5)],'default'),'learning-layer'); learnLayer.defaultNode=learning;
const releaseLayer = new LayerObject([release],[],new LayerLayoutObject([new NodePlacementObject(release,0.5,0.5)],'default'),'release-layer'); releaseLayer.defaultNode=release;
const learnAction={kind:'navigate',relation:'expand',sourceLayer:root,label:'Inside the learning loop',icon:'brain',target:learnLayer,clientKey:'expand-learning'};
const releaseAction={kind:'navigate',relation:'expand',sourceLayer:root,label:'Release checks & serving',icon:'clipboard-check',target:releaseLayer,clientKey:'expand-release'};
data.detailAuthoring.setComponent('main',html"'`<section class="page"><h2>1 · Prepare raw text</h2><p class="lead">Build a corpus whose quality and coverage match the model’s intended use.</p><div class="flow"><span class="step">Collect</span><span>→</span><span class="step">Clean & deduplicate</span><span>→</span><span class="step">Filter & mix</span><span>→</span><span class="step">Separate evaluation data</span></div><p>Sources can include web pages, books, code and domain documents. Track provenance and permitted use; remove malformed content and sensitive information where appropriate. Balance sources, languages and domains instead of letting volume alone set the mixture.</p><p>Deduplication reduces repetition and leakage. Keep validation and test material separate, and check for overlap with training text and benchmarks.</p><div class="note"><strong>Output:</strong> a versioned corpus. Data choices strongly influence what the model learns, including its biases and gaps.</div></section>`,style);
tokens.detailAuthoring.setComponent('"'main',html"'`<section class="page"><h2>2 · Turn text into training examples</h2><p class="lead">A tokenizer converts text into discrete IDs the transformer can process.</p><p>Typically, a subword or byte-based tokenizer uses a fixed vocabulary. Tokens are pieces of text, not necessarily whole words. Learn or choose the tokenizer, then encode the corpus consistently.</p><div class="flow"><span class="step">Text</span><span>→</span><span class="step">Token IDs</span><span>→</span><span class="step">Context-length sequences</span><span>→</span><span class="step">Batches</span></div><p>Pack or split sequences to fit the context window. Handle document boundaries, padding and loss masks deliberately. For next-token training, targets are the sequence shifted one position: each position predicts the token that follows it.</p><div class="note"><strong>Tradeoff:</strong> longer contexts provide more context but increase memory and computation; tokenization affects sequence length and language coverage.</div></section>`,style);
train.detailAuthoring.setComponent('"'main',html"'`<section class="page"><h2>Raw text → deployed language model</h2><p class="lead">Text supplies prediction examples. Training changes the transformer’s weights; deployment uses those weights to generate tokens.</p><div class="flow"><span class="step">1 · Curate text</span><span>→</span><span class="step">2 · Tokenize</span><span>→</span><span class="step">3 · Pretrain</span><span>→</span><span class="step">4 · Adapt</span><span>→</span><span class="step">5 · Release</span></div><h3>3 · Learn by predicting the next token</h3><p>A randomly initialized decoder-only transformer reads earlier tokens and predicts the next one. Compare its probability distribution with the actual token, compute gradients, and update the weights. Repeat over many batches, checking held-out loss and saving checkpoints.</p><p>The result is a <strong>base model</strong> that learns patterns in language and other training content. Useful behavior and factual reliability still need evaluation.</p><div class="note">This map describes a typical causal language model. Architectures and post-training recipes vary; instruction tuning is common but optional. Evaluation happens throughout the process, and production feedback informs later versions.</div><button ${detailCapability.expand(learnAction)}>Inside the learning loop</button></section>`,style);
adapt.detailAuthoring.setComponent('"'main',html"'`<section class="page"><h2>4 · Shape the model’s behavior</h2><p class="lead">Post-training makes a base model more useful for a particular task or interaction style.</p><h3>Supervised fine-tuning</h3><p>Train on examples of prompts and desired responses, using the same next-token objective. Loss is often applied primarily to response tokens. Domain adaptation can also continue pretraining on specialized text.</p><h3>Preference optimization</h3><p>Use human or model-assisted comparisons to favor better responses. Methods include direct preference optimization (DPO) and reinforcement learning with a reward model, often called RLHF when human feedback supplies preferences.</p><div class="note"><strong>Tradeoff:</strong> behavior improvements can affect general capability or overfit to the feedback signal. Compare against the base model and validate with independent examples. Training budgets, data quality and intended use determine which steps are worthwhile.</div></section>`,style);
deploy.detailAuthoring.setComponent('"'main',html"'`<section class="page"><h2>5 · Evaluate, then deploy</h2><p class="lead">A low training loss is not a release decision. Test the behavior users will actually depend on.</p><p>Check held-out performance, target tasks, robustness, factual errors and relevant safety or privacy risks. Test the served configuration too: quantization, decoding settings and system instructions can change results.</p><div class="flow"><span class="step">Select checkpoint</span><span>→</span><span class="step">Evaluate</span><span>→</span><span class="step">Optimize serving</span><span>→</span><span class="step">Release & monitor</span></div><p>Serve by repeatedly predicting and selecting a next token. Monitor quality, latency, cost and failures; maintain rollback options. Curated feedback can drive a new data and training cycle.</p><div class="note">Ordinary inference uses fixed weights. Conversations do not automatically retrain the model; later training is a separate process.</div><button ${detailCapability.expand(releaseAction)}>Release checks & serving</button></section>`,style);
learning.detailAuthoring.setComponent('"'main',html"'`<section class="page"><h2>Inside the pretraining loop</h2><p class="lead">Each batch produces predictions, a loss and a weight update.</p><div class="flow"><span class="step">Token IDs</span><span>→</span><span class="step">Embeddings + positions</span><span>→</span><span class="step">Transformer blocks</span><span>→</span><span class="step">Vocabulary probabilities</span></div><h3>Forward pass: combine context</h3><p>Each block uses causal self-attention and a feed-forward network, with residual connections and normalization. Attention forms queries, keys and values; weights come from <code>softmax(QKᵀ / √d + causal mask)</code>. The mask prevents a position from reading future tokens. Position information preserves token order.</p><h3>Objective: reward correct predictions</h3><p>For tokens x₁…xₜ, minimize <code>L = −Σₜ log pθ(xₜ | x₁…xₜ₋₁)</code>, usually averaged over eligible tokens. A vocabulary projection and softmax yield the predicted distribution. During training, the actual earlier tokens supply context, and all positions can be evaluated in parallel.</p><h3>Backward pass: update parameters</h3><p>Backpropagation computes gradients of the loss. An optimizer such as AdamW updates embeddings, attention, feed-forward and output parameters. Learning-rate schedules, gradient clipping and mixed precision support stable, efficient training. Large runs often distribute work across accelerators and accumulate gradients.</p><div class="note"><strong>Repeat & check:</strong> monitor held-out loss, numerical stability and task evaluations; checkpoint weights and optimizer state. Next-token accuracy encourages useful representations but does not guarantee truthfulness or reasoning reliability.</div></section>`,style);
release.detailAuthoring.setComponent('"'main',html"'`<section class="page"><h2>From trained checkpoint to usable service</h2><p class="lead">Release requires both measured model behavior and an inference system that meets practical constraints.</p><table><thead><tr><th scope="col">Decision</th><th scope="col">Evidence or mechanism</th></tr></thead><tbody><tr><td>Is the model useful?</td><td>Held-out loss, task benchmarks and representative human evaluations. Check contamination and compare with a baseline.</td></tr><tr><td>Is it suitable for this use?</td><td>Test factual errors, robustness, bias, privacy leakage and misuse risks relevant to the application. Benchmark scores cover only the cases tested.</td></tr><tr><td>Can it be served efficiently?</td><td>Batching and key/value caching reduce inference overhead. Quantization reduces memory; distillation can produce a smaller model. Recheck quality after changes.</td></tr><tr><td>Does the whole service work?</td><td>Measure latency, throughput, memory and cost at expected load. Validate prompts, decoding and any tools or retrieval used by the application.</td></tr><tr><td>What happens after release?</td><td>Monitor failures and quality with appropriate data handling; version releases and keep rollback paths. Review feedback before incorporating it into later training.</td></tr></tbody></table><div class="note"><strong>Inference:</strong> encode the prompt, compute next-token probabilities, select a token with the chosen decoding rule, append it and repeat until a stopping condition. Weight updates happen in training, not in this generation loop.</div></section>`,style);
for(const n of [...rootNodes,learning,release]) { await graph.checkpointNodeDetail(n); const r=await graph.submitNode(n); console.log('"'NODE',n.title,r.preview?.path ?? r.preview?.status); }
for(const e of edges) await graph.submitEdge(e);
for(const l of [learnLayer,releaseLayer,root]) { const r=await graph.submitLayer(l); console.log('LAYER',l.clientKey,r.preview?.path ?? r.preview?.status); }
await graph.addAction(train,learnAction);
await graph.addAction(deploy,releaseAction);
await graph.addAction(49,{kind:'navigate',relation:'expand',label:'Transformer training map',icon:'brain',target:root,clientKey:'training-map-response'});
if(current.currentLayerId) await graph.addAction(data,{kind:'navigate',relation:'reference',sourceLayer:root,label:'Prior context',target:current.currentLayerId,clientKey:'prior-context'});
RELAYER_GRAPH_PROGRAM"

