release.detailAuthoring.setComponent('main',html`<section class="page"><h2>From trained checkpoint to usable service</h2><p class="lead">Release requires both measured model behavior and an inference system that meets practical constraints.</p><table><thead><tr><th scope="col">Decision</th><th scope="col">Evidence or mechanism</th></tr></thead><tbody><tr><td>Is the model useful?</td><td>Held-out loss, task benchmarks and representative human evaluations. Check contamination and compare with a baseline.</td></tr><tr><td>Is it suitable for this use?</td><td>Test factual errors, robustness, bias, privacy leakage and misuse risks relevant to the application. Benchmark scores cover only the cases tested.</td></tr><tr><td>Can it be served efficiently?</td><td>Batching and key/value caching reduce inference overhead. Quantization reduces memory; distillation can produce a smaller model. Recheck quality after changes.</td></tr><tr><td>Does the whole service work?</td><td>Measure latency, throughput, memory and cost at expected load. Validate prompts, decoding and any tools or retrieval used by the application.</td></tr><tr><td>What happens after release?</td><td>Monitor failures and quality with appropriate data handling; version releases and keep rollback paths. Review feedback before incorporating it into later training.</td></tr></tbody></table><div class="note"><strong>Inference:</strong> encode the prompt, compute next-token probabilities, select a token with the chosen decoding rule, append it and repeat until a stopping condition. Weight updates happen in training, not in this generation loop.</div></section>`,style);
for(const n of [...rootNodes,learning,release]) { await graph.checkpointNodeDetail(n); const r=await graph.submitNode(n); console.log('NODE',n.title,r.preview?.path ?? r.preview?.status); }
for(const e of edges) await graph.submitEdge(e);
for(const l of [learnLayer,releaseLayer,root]) { const r=await graph.submitLayer(l); console.log('LAYER',l.clientKey,r.preview?.path ?? r.preview?.status); }
await graph.addAction(train,learnAction);
await graph.addAction(deploy,releaseAction);
await graph.addAction(49,{kind:'navigate',relation:'expand',label:'Transformer training map',icon:'brain',target:root,clientKey:'training-map-response'});
if(current.currentLayerId) await graph.addAction(data,{kind:'navigate',relation:'reference',sourceLayer:root,label:'Prior context',target:current.currentLayerId,clientKey:'prior-context'});
